WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM web_events), flagged AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessions_web_events AS (SELECT id, session_id, event_time, duration_sec, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged), with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions_web_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM islands), sessions_web_events_2 AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY session_start_flag DESC NULLS FIRST, id) AS row_num FROM sessions_web_events_2 QUALIFY row_num = 1), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time FROM latest WHERE event_time > DATE '2023-05-06' AND burst_id < 3) SELECT p.country, COUNT(*) AS rows_total, ROUND(AVG(s.island_id), 2) AS avg_island_id FROM cleaned s LEFT JOIN sessions p ON s.session_id = p.id GROUP BY p.country
